  "RENDER_WGSL": "\n\nstruct Params {\n  grid: vec4<f32>,\n  mouse: vec4<f32>,\n  sim: vec4<f32>,\n  pointerDelta: vec4<f32>,\n  viewport: vec4<f32>,\n}\n\nfn idx_at(x: i32, y: i32) -> u32 {\n  let w = i32(u.grid.x);\n  let h = i32(u.grid.y);\n  let cx = clamp(x, 0, w - 1);\n  let cy = clamp(y, 0, h - 1);\n  return u32(cy * w + cx);\n}\n\nfn uv_to_grid(uv: vec2<f32>) -> vec2<f32> {\n  return uv * u.grid.xy - vec2<f32>(0.5, 0.5);\n}\n\nfn safe_norm(v: vec2<f32>) -> vec2<f32> {\n  return v / max(length(v), 1e-5);\n}\n\nfn pointer_falloff(uv: vec2<f32>, radius: f32) -> f32 {\n  // A capsule covers the entire stroke, including movement between rendered frames.\n  let stroke = u.pointerDelta.xy;\n  let start = u.mouse.xy - stroke;\n  let along = clamp(dot(uv - start, stroke) / max(dot(stroke, stroke), 1e-8), 0.0, 1.0);\n  let distance = length(uv - (start + along * stroke));\n  return (1.0 - smoothstep(0.0, radius, distance)) * u.mouse.z;\n}\n\n\nstruct VSOut {\n  @builtin(position) position: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n  @location(1) materialUV: vec2<f32>,\n}\n\n@group(0) @binding(0) var<uniform> u: Params;\n@group(0) @binding(1) var<storage, read> dyeBuf: array<vec4<f32>>;\n@group(0) @binding(2) var<storage, read> velBuf: array<vec4<f32>>;\n@group(0) @binding(3) var<storage, read> divCurl: array<vec4<f32>>;\n\nfn dye_at(x: i32, y: i32) -> vec3<f32> {\n  return dyeBuf[idx_at(x, y)].xyz;\n}\n\nfn vel_at(x: i32, y: i32) -> vec2<f32> {\n  return velBuf[idx_at(x, y)].xy;\n}\n\nfn curl_at(x: i32, y: i32) -> f32 {\n  return divCurl[idx_at(x, y)].y;\n}\n\nfn scalar_height(dye: vec3<f32>, vel: vec2<f32>, curl: f32) -> f32 {\n  return clamp(length(dye) * 0.64 + abs(curl) * 0.016 + length(vel) * 0.10, 0.0, 1.3);\n}\n\nfn spectral(t: f32) -> vec3<f32> {\n  return 0.5 + 0.5 * cos(vec3<f32>(0.0, 2.0, 4.0) + t * 6.28318);\n}\n\n@group(0) @binding(4) var<storage, read> materialDestinations: array<vec4<f32>>;\nfn materialViewport() -> vec2<f32> { return u.viewport.xy; }\n\nfn materialCoverage(uv: vec2<f32>) -> f32 {\n  let p = clamp(uv * u.grid.xy - 0.5, vec2<f32>(0.0), u.grid.xy - 1.0);\n  let base = vec2<i32>(floor(p)); let f = fract(p);\n  let coverage = mix(mix(materialDestinations[idx_at(base.x, base.y)].z,\n    materialDestinations[idx_at(base.x + 1, base.y)].z, f.x),\n    mix(materialDestinations[idx_at(base.x, base.y + 1)].z,\n      materialDestinations[idx_at(base.x + 1, base.y + 1)].z, f.x), f.y);\n  // Geometry moves first. Only its final silhouette is constrained to the mark.\n  let shape = smoothstep(0.35, 1.0, u.sim.w);\n  return mix(1.0, coverage, shape);\n}\n@vertex\nfn vs(@builtin(vertex_index) vertexIndex: u32) -> VSOut {\n  let corners = array<vec2<f32>, 4>(vec2<f32>(0.0, 0.0), vec2<f32>(1.0, 0.0),\n    vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 1.0));\n  let source = corners[vertexIndex];\n  let destination = mix(materialDestinations[0].xy, materialDestinations[1].xy, source);\n  let position = mix(source, destination, u.sim.w);\n  var out: VSOut;\n  out.position = vec4<f32>((position * 2.0 - 1.0) / materialViewport(), 0.0, 1.0);\n  out.uv = source;\n  out.materialUV = position;\n  return out;\n}\n\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4<f32> {\n  let gridPos = uv_to_grid(clamp(in.uv, u.grid.zw * 0.5, vec2<f32>(1.0) - u.grid.zw * 0.5));\n  let gx = i32(floor(gridPos.x));\n  let gy = i32(floor(gridPos.y));\n  let cell = fract(gridPos);\n  // Reuse the four dye samples for color, relief and local contrast.\n  let d00 = dye_at(gx, gy);\n  let d10 = dye_at(gx + 1, gy);\n  let d01 = dye_at(gx, gy + 1);\n  let d11 = dye_at(gx + 1, gy + 1);\n  let dye = mix(mix(d00, d10, cell.x), mix(d01, d11, cell.x), cell.y);\n  let v00 = vel_at(gx, gy); let v10 = vel_at(gx + 1, gy);\n  let v01 = vel_at(gx, gy + 1); let v11 = vel_at(gx + 1, gy + 1);\n  let c00 = curl_at(gx, gy); let c10 = curl_at(gx + 1, gy);\n  let c01 = curl_at(gx, gy + 1); let c11 = curl_at(gx + 1, gy + 1);\n  let vel = mix(mix(v00, v10, cell.x), mix(v01, v11, cell.x), cell.y);\n  let curl = mix(mix(c00, c10, cell.x), mix(c01, c11, cell.x), cell.y);\n  let speed = length(vel);\n  // Interpolate the actual height derivatives instead of stepping normals at cell borders.\n  let h00 = scalar_height(d00, v00, c00);\n  let h10 = scalar_height(d10, v10, c10);\n  let h01 = scalar_height(d01, v01, c01);\n  let h11 = scalar_height(d11, v11, c11);\n  let hc = mix(mix(h00, h10, cell.x), mix(h01, h11, cell.x), cell.y);\n  let grad = vec2<f32>(mix(h10 - h00, h11 - h01, cell.y),\n    mix(h01 - h00, h11 - h10, cell.x));\n  let localMean = (d00 + d10 + d01 + d11) * 0.25;\n  let crispDye = max(vec3<f32>(0.0), dye + (dye - localMean) * 0.18);\n  let normal = normalize(vec3<f32>(-grad.x * 1.25, -grad.y * 1.25, 1.0));\n  let view = normalize(vec3<f32>(0.0, 0.0, 1.0));\n  let fresnel = pow(1.0 - max(dot(normal, view), 0.0), 3.0);\n  let prism = spectral(hc * 0.22 + abs(curl) * 0.36 + u.sim.y * 0.020);\n  let secondary = spectral(speed * 0.30 + normal.x * 0.15 - normal.y * 0.08);\n  let glint = pow(max(dot(reflect(normalize(vec3<f32>(0.20, -0.16, -1.0)), normal), view), 0.0), 20.0);\n  let fluidGlow = crispDye * (0.92 + speed * 0.24) + prism * abs(curl) * 0.030;\n  let metallic = mix(vec3<f32>(0.05, 0.06, 0.08), prism, 0.52)\n    + secondary * fresnel * 0.22\n    + vec3<f32>(1.0, 0.96, 0.93) * glint * 0.34;\n  let base = fluidGlow + metallic * (0.22 + hc * 0.14);\n  let bg = vec3<f32>(0.04, 0.055, 0.07);\n  let color = vec3<f32>(1.0) - exp(-max(base, vec3<f32>(0.0)) * 1.65);\n  return vec4<f32>(mix(bg, max(color, bg), materialCoverage(in.materialUV)), 1.0);\n}\n",
