  "FADE_WGSL": "\nstruct VSOut {\n  @builtin(position) position: vec4<f32>,\n  @location(0) uv: vec2<f32>,\n}\n\n@group(0) @binding(0) var linearSampler: sampler;\n@group(0) @binding(1) var historyTex: texture_2d<f32>;\n\n@vertex\nfn vs(@builtin(vertex_index) vertexIndex: u32) -> VSOut {\n  var positions = array<vec2<f32>, 3>(\n    vec2<f32>(-1.0, -3.0),\n    vec2<f32>(-1.0,  1.0),\n    vec2<f32>( 3.0,  1.0)\n  );\n  let pos = positions[vertexIndex];\n  var out: VSOut;\n  out.position = vec4<f32>(pos, 0.0, 1.0);\n  out.uv = pos * vec2<f32>(0.5, -0.5) + vec2<f32>(0.5, 0.5);\n  return out;\n}\n\n@fragment\nfn fs(in: VSOut) -> @location(0) vec4<f32> {\n  let prev = textureSample(historyTex, linearSampler, in.uv);\n  let dimensions = vec2<f32>(textureDimensions(historyTex));\n  let uv = (in.uv * 2.0 - 1.0) * dimensions / max(dimensions.x, dimensions.y);\n  let vignette = 1.0 - smoothstep(0.15, 1.2, length(uv));\n  let background = vec3<f32>(0.010, 0.016, 0.013) + vignette * vec3<f32>(0.008, 0.020, 0.012);\n  let edgeVisibility = 1.0 - smoothstep(0.82, 0.96,\n    max(abs(uv.x), abs(uv.y)));\n  let faded = prev.rgb * (0.55 * edgeVisibility);\n  return vec4<f32>(max(faded, background), 1.0);\n}\n",
